import { createSlice } from "@reduxjs/toolkit";
import axios from "axios";

// Global token variable
const TOKEN = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..pjV3ADLMHpkalJNnh975EL-oiUUQ3aQ6xZv_ArXbxgg";

const vehicleSlice = createSlice({
    name: "vehicle",
    initialState: {
        vehicles: [],
        status: "idle", // "idle" | "loading" | "succeeded" | "failed"
        error: null,
    },
    reducers: {
        fetchVehiclesStart: (state) => {
            state.status = "loading";
            state.error = null;
        },
        fetchVehiclesSuccess: (state, action) => {
            state.status = "succeeded";
            state.vehicles = action.payload;
        },
        fetchVehiclesFailure: (state, action) => {
            state.status = "failed";
            state.error = action.payload;
        },
    },
});

export const { fetchVehiclesStart, fetchVehiclesSuccess, fetchVehiclesFailure } =
    vehicleSlice.actions;

export const fetchVehicles = () => async (dispatch) => {
    dispatch(fetchVehiclesStart());
    try {
        const response = await axios.get(
            `${import.meta.env.VITE_API_URL}/api/vehicle/get-all`,
            {
                headers: {
                    Authorization: `Bearer ${TOKEN}`, // 🔹 Added Authorization header
                },
            }
        );
        const data = response.data.devices.map((item) => ({
            name: item.name,
            model: item.model,
            category: item.category,
            _id: item._id,
        }));
        dispatch(fetchVehiclesSuccess(data));
    } catch (error) {
        dispatch(fetchVehiclesFailure(error.message));
    }
};

export default vehicleSlice.reducer;






